scenario.en:
function App() {
  const rows = useRows();
  return (
    <ScrollTracker>
      <HeavyTable rows={rows} />
    </ScrollTracker>
  );
}

function ScrollTracker({ children }) {
  const [y, setY] = useState(0);
  return (
    <div onScroll={(e) => setY(e.target.scrollTop)}>
      <ProgressBar y={y} />
      {children}
    </div>
  );
}

